def type_in_type_group(item, type_group):
    if isinstance(item, type_group):
        return True
    if isinstance(item, type) and issubclass(item, type_group):
        return True
    if isinstance(item, np_ndarray) and item.dtype.type in type_group:
        return True
    return False


def number_to_string(number, significant_digits, number_format_notation='f'):
    if number_format_notation not in number_formatting:
        raise ValueError("number_format_notation must be 'f' or 'e'")
    if significant_digits is not None:
        if isinstance(number, complex):
            real_str = number_formatting[number_format_notation] % number.real
            imag_str = number_formatting[number_format_notation] % number.imag
            return f"{real_str}+{imag_str}j"
        else:
            return number_formatting[number_format_notation] % number
    else:
        return str(number)
